import java.util.Locale;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class AsPathTests {

    private Container mockContainer;
    private Locale testLocale;

    @Before
    public void setUp() {
        mockContainer = mock(Container.class);
        testLocale = Locale.getDefault();
    }

    @Test
    public void testAsPathWithNullParentReturnsRootPath() {
        // Arrange
        ContainerPointer pointer = new ContainerPointer(mockContainer, testLocale);

        // Act
        String result = pointer.asPath();

        // Assert
        assertEquals("/", result);
    }

    @Test
    public void testAsPathWithNonNullParentDelegatesToParent() {
        // Arrange
        NodePointer mockParent = mock(NodePointer.class);
        ContainerPointer pointer = new ContainerPointer(mockParent, mockContainer);
        when(mockParent.asPath()).thenReturn("/parent/path");

        // Act
        String result = pointer.asPath();

        // Assert
        assertEquals("/parent/path", result);
        verify(mockParent).asPath();
    }

    @Test
    public void testAsPathWithNullParentAndDifferentLocale() {
        // Arrange
        Locale customLocale = Locale.FRANCE;
        ContainerPointer pointer = new ContainerPointer(mockContainer, customLocale);

        // Act
        String result = pointer.asPath();

        // Assert
        assertEquals("/", result);
    }

    @Test
    public void testAsPathIdempotentWithNullParent() {
        // Arrange
        ContainerPointer pointer = new ContainerPointer(mockContainer, testLocale);

        // Act
        String result1 = pointer.asPath();
        String result2 = pointer.asPath();

        // Assert
        assertEquals(result1, result2);
        assertEquals("/", result1);
    }

    @Test
    public void testAsPathIdempotentWithNonNullParent() {
        // Arrange
        NodePointer mockParent = mock(NodePointer.class);
        when(mockParent.asPath()).thenReturn("/test/path");
        ContainerPointer pointer = new ContainerPointer(mockParent, mockContainer);

        // Act
        String result1 = pointer.asPath();
        String result2 = pointer.asPath();

        // Assert
        assertEquals(result1, result2);
        assertEquals("/test/path", result1);
        verify(mockParent, times(2)).asPath();
    }

    @Test
    public void testAsPathWithParentReturningRootPath() {
        // Arrange
        NodePointer mockParent = mock(NodePointer.class);
        when(mockParent.asPath()).thenReturn("/");
        ContainerPointer pointer = new ContainerPointer(mockParent, mockContainer);

        // Act
        String result = pointer.asPath();

        // Assert
        assertEquals("/", result);
        verify(mockParent).asPath();
    }
}

