package org.apache.commons.jxpath.ri.parser;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

import java.io.StringReader;

public class GetSuffixTests {

    private SimpleCharStream stream;

    @Before
    public void setUp() {
        // Initialize with a StringReader for testing purposes
        stream = new SimpleCharStream(new StringReader("abcdefghijklmnopqrstuvwxyz"));
    }

    @Test
    public void testGetSuffixBasic() {
        // Read some characters to populate the buffer and advance bufpos
        for (int i = 0; i < 10; i++) {
            try {
                stream.readChar();
            } catch (java.io.IOException e) {
                fail("IOException during setup: " + e.getMessage());
            }
        }

        // Now get a suffix of length 5
        char[] suffix = stream.GetSuffix(5);
        assertNotNull("Returned array should not be null", suffix);
        assertEquals("Suffix length should match requested length", 5, suffix.length);
        assertArrayEquals("Suffix content should match expected", new char[]{'f', 'g', 'h', 'i', 'j'}, suffix);
    }

    @Test
    public void testGetSuffixWithWrapAround() {
        // Create a small buffer to force wrap-around
        SimpleCharStream smallStream = new SimpleCharStream(new StringReader("abcdefghijklmnop"), 1, 1, 8);

        // Read enough characters to cause wrapping
        for (int i = 0; i < 12; i++) {
            try {
                smallStream.readChar();
            } catch (java.io.IOException e) {
                fail("IOException during setup: " + e.getMessage());
            }
        }

        // Get a suffix that spans the buffer wrap
        char[] suffix = smallStream.GetSuffix(5);
        assertNotNull("Returned array should not be null", suffix);
        assertEquals("Suffix length should match requested length", 5, suffix.length);
        // Expected content depends on how the buffer wraps, but it should contain 5 chars
    }

    @Test
    public void testGetSuffixFullBuffer() {
        // Fill the buffer completely
        for (int i = 0; i < 26; i++) { // Our test string has 26 chars
            try {
                stream.readChar();
            } catch (java.io.IOException e) {
                fail("IOException during setup: " + e.getMessage());
            }
        }

        // Request a suffix of the full buffer size (or part of it)
        char[] suffix = stream.GetSuffix(10);
        assertNotNull("Returned array should not be null", suffix);
        assertEquals("Suffix length should match requested length", 10, suffix.length);
        // Last 10 characters of alphabet
        assertArrayEquals("Suffix content should match expected", 
                         new char[]{'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z'}, suffix);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testGetSuffixLengthExceedsBufferSize() {
        // Try to get a suffix longer than the buffer
        stream.GetSuffix(5000); // Much larger than default buffer size of 4096
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testGetSuffixZeroLength() {
        // Length of 0 should throw exception per precondition
        stream.GetSuffix(0);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testGetSuffixNegativeLength() {
        // Negative length should throw exception
        stream.GetSuffix(-1);
    }

    @Test
    public void testGetSuffixSingleCharacter() {
        try {
            stream.readChar(); // Read one character ('a')
        } catch (java.io.IOException e) {
            fail("IOException during setup: " + e.getMessage());
        }

        char[] suffix = stream.GetSuffix(1);
        assertNotNull("Returned array should not be null", suffix);
        assertEquals("Suffix length should be 1", 1, suffix.length);
        assertEquals("Suffix should contain first character", 'a', suffix[0]);
    }

    @Test
    public void testGetSuffixDoesNotModifyInternalState() {
        // Capture initial state
        int initialBufPos = stream.bufpos;

        try {
            // Read a few characters
            for (int i = 0; i < 5; i++) {
                stream.readChar();
            }

            initialBufPos = stream.bufpos;

            // Call GetSuffix
            stream.GetSuffix(3);

            // Verify state hasn't changed
            assertEquals("bufpos should remain unchanged", initialBufPos, stream.bufpos);

        } catch (java.io.IOException e) {
            fail("IOException during test: " + e.getMessage());
        }
    }
}

