    public void setUp() {
        collection = new Object();
        collectionPointer = new CollectionPointer(collection, Locale.getDefault());
    }

    @Test
    public void testNamespacePointerWhenIndexIsWholeCollectionReturnsNull() {
        // Set up the collection pointer to represent the whole collection
        collectionPointer.setIndex(NodePointer.WHOLE_COLLECTION);

        NodePointer result = collectionPointer.namespacePointer("testNamespace");

        assertNull("Should return null when index is WHOLE_COLLECTION", result);
    }

