import org.apache.commons.jxpath.ri.compiler.NodeNameTest;
import org.apache.commons.jxpath.ri.compiler.NodeTest;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class NextNodeTests {

    private EvalContext parentContext;
    private NodePointer nodePointer;
    private NodeTest nodeNameTest;
    private NamespaceContext namespaceContext;

    @Before
    public void setUp() {
        parentContext = mock(EvalContext.class);
        nodePointer = mock(NodePointer.class);
        nodeNameTest = new NodeNameTest(new QName(null, "test"));
    }

    @Test
    public void testNextNodeWithValidParentAndMatchingNode() {
        // Arrange
        when(parentContext.nextSet()).thenReturn(true);
        when(parentContext.getCurrentNodePointer()).thenReturn(nodePointer);
        when(nodePointer.namespaceIterator()).thenReturn(null);
        when(nodePointer.isLeaf()).thenReturn(false);

        namespaceContext = new NamespaceContext(parentContext, nodeNameTest);

        // Act
        boolean result = namespaceContext.nextNode();

        // Assert
        assertFalse(result);
    }

    @Test
    public void testNextNodeWithNoMoreSets() {
        // Arrange
        when(parentContext.nextSet()).thenReturn(false);

        namespaceContext = new NamespaceContext(parentContext, nodeNameTest);

        // Act
        boolean result = namespaceContext.nextNode();

        // Assert
        assertFalse(result);
    }

    @Test
    public void testNextNodeWithNullCurrentNodePointer() {
        // Arrange
        when(parentContext.nextSet()).thenReturn(true);
        when(parentContext.getCurrentNodePointer()).thenReturn(null);

        namespaceContext = new NamespaceContext(parentContext, nodeNameTest);

        // Act
        boolean result = namespaceContext.nextNode();

        // Assert
        assertFalse(result);
    }

    @Test
    public void testNextNodeWithWildcardNodeTest() {
        // Arrange
        NodeTest wildcardTest = new NodeNameTest(new QName(null, "*"));
        when(parentContext.nextSet()).thenReturn(true);
        when(parentContext.getCurrentNodePointer()).thenReturn(nodePointer);
        when(nodePointer.namespaceIterator()).thenReturn(null);
        when(nodePointer.isLeaf()).thenReturn(false);

        namespaceContext = new NamespaceContext(parentContext, wildcardTest);

        // Act
        boolean result = namespaceContext.nextNode();

        // Assert
        assertFalse(result);
    }

    @Test
    public void testNextNodeWithInvalidNodeTestType() {
        // Arrange
        NodeTest invalidTest = mock(NodeTest.class);
        when(parentContext.nextSet()).thenReturn(true);
        when(parentContext.getCurrentNodePointer()).thenReturn(nodePointer);

        namespaceContext = new NamespaceContext(parentContext, invalidTest);

        // Act
        boolean result = namespaceContext.nextNode();

        // Assert
        assertFalse(result);
    }

    @Test
    public void testNextNodeWhenParentContextReturnsTrueOnNextSet() {
        // Arrange
        when(parentContext.nextSet()).thenReturn(true).thenReturn(false);
        when(parentContext.getCurrentNodePointer()).thenReturn(nodePointer);
        when(nodePointer.namespaceIterator()).thenReturn(null);
        when(nodePointer.isLeaf()).thenReturn(false);

        namespaceContext = new NamespaceContext(parentContext, nodeNameTest);

        // First call
        boolean firstResult = namespaceContext.nextNode();
        assertFalse(firstResult);

        // Second call should also return false
        boolean secondResult = namespaceContext.nextNode();
        assertFalse(secondResult);
    }

    @Test
    public void testNextNodeWithLeafNodePointer() {
        // Arrange
        when(parentContext.nextSet()).thenReturn(true);
        when(parentContext.getCurrentNodePointer()).thenReturn(nodePointer);
        when(nodePointer.isLeaf()).thenReturn(true);

        namespaceContext = new NamespaceContext(parentContext, nodeNameTest);

        // Act
        boolean result = namespaceContext.nextNode();

        // Assert
        assertFalse(result);
    }
}

