    public static class TestObject {
        private String value;
        private int number;
        private ExpressionContext context;

        // No-arg constructor
        public TestObject() {
            this.value = "default";
            this.number = 0;
        }

        // Constructor with parameters
        public TestObject(String value, int number) {
            this.value = value;
            this.number = number;
